16	export interface WalletTransaction {
17	    id: string;
18	    wallet_id: string;
19	    amount: number;
20	    type: 'credit' | 'debit' | 'escrow_reserve' | 'escrow_release' | 'initial_balance' | 'platform_fee' | 'escrow_authorize' | 'escrow_void';
21	    description: string | null;
