26	export interface EscrowTransaction {
27	    id: string;
28	    job_id: string;
29	    application_id: string | null;
30	    amount: number;
31	    company_wallet_id: string;
32	    worker_wallet_id: string | null;
33	    // Postpago (Slice 2): 'authorized'/'captured' coexistem com os estados prepago.
34	    status: 'reserved' | 'authorized' | 'captured' | 'released' | 'refunded';
35	    // prepaid = pull legado (saldo); postpaid = push Slice 2 (hold no cartão). Default 'prepaid' no DB.
36	    kind?: 'prepaid' | 'postpaid';
37	    // id da cobrança no Asaas (authorizeOnly:true). NULL para prepago.
38	    asaas_payment_id?: string | null;
39	    authorized_at?: string | null;
40	    captured_at?: string | null;
41	    created_at: string;
42	    released_at: string | null;
43	    job?: { title: string };
44	}
